//! Derived zone-v1 product contract DTOs and validators (auth/common v1).
//!
//! Assembled by sudostack from the pinned owner revisions: nexus owns the
//! product schemas, nexus-vfs owns zone-id/zone-path — the validation rules
//! for both are generated by `build.rs` from the materialized owner specs, so
//! this crate never restates (and can never disagree with) an owner rule.
//! Rust consumers join the TS package in facing the same fixture corpus
//! (`crates/sudo-contracts/tests/conformance.rs`).
//!
//! Structure vs. value rules: serde owns the structural layer (required
//! fields, closed enums, unknown-optional tolerance — serde ignores unknown
//! fields, which is exactly the wire rule); each DTO's `validate()` owns the
//! value layer (api_version consts, zone-id/path projections, digest/decimal/
//! timestamp shapes). A payload is contract-valid only when both layers pass.

mod rules {
    include!(concat!(env!("OUT_DIR"), "/generated_rules.rs"));

    /// Format check against the generated charset/length/edge constants.
    pub fn validate_format(s: &str) -> bool {
        let chars: Vec<char> = s.chars().collect();
        if chars.len() < ZONE_ID_MIN_LEN || chars.len() > ZONE_ID_MAX_LEN {
            return false;
        }
        if chars.first() == Some(&ZONE_ID_NO_LEADING) || chars.last() == Some(&ZONE_ID_NO_TRAILING) {
            return false;
        }
        chars.iter().all(|c| ZONE_ID_CHARSET.contains(*c))
    }

    /// Path check against the generated zone-path constants: absolute, no
    /// empty/forbidden components, no reserved prefixes, depth/length bounds,
    /// allowed charset.
    pub fn validate_path(s: &str) -> bool {
        if !s.starts_with('/') || s.len() > ZONE_PATH_MAX_LEN {
            return false;
        }
        if s == "/" {
            return true;
        }
        let components: Vec<&str> = s[1..].split('/').collect();
        if components.len() > ZONE_PATH_MAX_DEPTH {
            return false;
        }
        if ZONE_PATH_RESERVED_PREFIXES.contains(&components[0]) {
            return false;
        }
        components.iter().all(|c| {
            !c.is_empty()
                && c.len() <= 255
                && !ZONE_PATH_FORBIDDEN_COMPONENTS.contains(c)
                && c.chars().all(|ch| ZONE_PATH_COMPONENT_ALLOWED.contains(ch))
        })
    }
}

