#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Zone {
    pub api_version: String,
    pub kind: String,
    pub zone_id: String,
    pub display_name: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    pub status: ZoneStatus,
    pub deployment: ZoneDeployment,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub labels: Option<HashMap<String, String>>,
    pub revision: String,
    pub created_by: PrincipalRef,
    pub created_at: String,
    pub updated_at: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub deleted_at: Option<String>,
}

impl Validate for Zone {
    fn validate(&self) -> Result<(), ContractViolation> {
        (self.api_version == API_VERSION_AUTH_V1).then_some(()).ok_or(ContractViolation { field: "api_version" })?;
        (self.kind == "Zone").then_some(()).ok_or(ContractViolation { field: "kind" })?;
        validate_existing_zone_id_ref(&self.zone_id).then_some(()).ok_or(ContractViolation { field: "zone_id" })?;
        (!self.display_name.is_empty()).then_some(()).ok_or(ContractViolation { field: "display_name" })?;
        (!self.revision.is_empty()).then_some(()).ok_or(ContractViolation { field: "revision" })?;
        is_rfc3339(&self.created_at).then_some(()).ok_or(ContractViolation { field: "created_at" })?;
        is_rfc3339(&self.updated_at).then_some(()).ok_or(ContractViolation { field: "updated_at" })?;
        if let Some(d) = &self.deleted_at {
            is_rfc3339(d).then_some(()).ok_or(ContractViolation { field: "deleted_at" })?;
        }
        self.created_by.validate()?;
        self.deployment.validate()?;
        Ok(())
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ZoneCreateRequest {
    pub api_version: String,
    pub kind: String,
    pub zone_id: String,
    pub display_name: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub deployment: Option<ZoneDeployment>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub labels: Option<HashMap<String, String>>,
}

impl Validate for ZoneCreateRequest {
    fn validate(&self) -> Result<(), ContractViolation> {
        (self.api_version == API_VERSION_AUTH_V1).then_some(()).ok_or(ContractViolation { field: "api_version" })?;
        (self.kind == "ZoneCreateRequest").then_some(()).ok_or(ContractViolation { field: "kind" })?;
        // Create admission uses the STRICT tenant projection: reserved ids are
        // rejected here even though the record validator would accept them.
        validate_tenant_zone_id_create(&self.zone_id).then_some(()).ok_or(ContractViolation { field: "zone_id" })?;
        (!self.display_name.is_empty()).then_some(()).ok_or(ContractViolation { field: "display_name" })?;
        if let Some(d) = &self.deployment {
            d.validate()?;
        }
        Ok(())
    }
}

