/// Inline ErrorInfo (§4.10). Clients judge by code/retryable, never message.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ErrorInfo {
    pub code: String,
    pub message: String,
    pub retryable: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub details: Option<serde_json::Value>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cause_ref: Option<ResourceRef>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub request_id: Option<String>,
}

impl ErrorInfo {
    pub fn is_unknown_code(&self) -> bool {
        !KNOWN_ERROR_CODES.contains(&self.code.as_str())
    }
}

impl Validate for ErrorInfo {
    fn validate(&self) -> Result<(), ContractViolation> {
        let wellformed = self
            .code
            .bytes()
            .all(|b| b.is_ascii_uppercase() || b.is_ascii_digit() || b == b'_')
            && self.code.starts_with(|c: char| c.is_ascii_uppercase())
            && !self.code.is_empty();
        wellformed.then_some(()).ok_or(ContractViolation { field: "code" })?;
        if let Some(r) = &self.cause_ref {
            r.validate()?;
        }
        Ok(())
    }
}

